const saved=read();let state=reconcileCatalog({products:structuredClone(seedProducts),settings:structuredClone(config),cart:[],favorites:[],profile:null,addresses:[],orders:[],audit:[],selectedBranchId:'',...saved},seedProducts,config.catalogVersion);
