function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function audit(action){state.audit.unshift({id:crypto.randomUUID(),at:new Date().toISOString(),actor:state.profile?.name||'Administrador',action});state.audit=state.audit.slice(0,250)}
function route(){const [path,query]=(location.hash.slice(1)||'/').split('?');return{path,params:new URLSearchParams(query||'')}}
function goto(url){if(location.hash==='#'+url)render();else location.hash=url}
function calc(){return totals(state.cart,state.products)}
function saleLabel(p,qty=1){return p.saleUnit==='bulto'?(qty===1?'bulto':'bultos'):(qty===1?'caja':'cajas')}
