function brand(){return `<a class="brand" href="#/" aria-label="La Montevideana, inicio">${state.settings.logoConfirmed?`<img class="official-logo" src="${esc(state.settings.logo)}" alt="Logo de ${esc(state.settings.name)}" width="2003" height="1458"><span class="brand-type"><small>MINORISTA Y MAYORISTA</small><strong>${esc(state.settings.name)}</strong></span>`:`<span class="brand-type"><small>MINORISTA Y MAYORISTA</small><strong>${esc(state.settings.name)}</strong></span>`}</a>`}
function header(){const{path}=route();return `<div class="topbar"><div class="container"><span class="location">${icon('store')}Distribución para heladerías</span><span>Minorista y mayorista · Cajas y bultos</span></div></div><header class="header"><div class="container"><div class="header-main">${brand()}<form class="search" data-form="search" role="search"><input name="q" aria-label="Buscar productos por caja o bulto" placeholder="Buscá productos para tu heladería" value="${esc(route().params.get('q')||'')}"><button aria-label="Buscar">${icon('search')}</button></form><div class="header-tools"><a class="tool favorites-tool" href="#/cuenta?tab=favoritos" aria-label="Favoritos">${icon('heart')}</a><a class="tool" href="#/cuenta">${icon('user')}<span class="tool-text"><small>Tu comercio</small><strong>Mi cuenta</strong></span></a><button class="tool" data-action="cart" aria-label="Abrir pedido, ${calc().count} cajas o bultos"><span class="cart-icon">${icon('bag')}<span class="count">${calc().count}</span></span><span class="tool-text"><small>Tu pedido</small><strong>${money(calc().subtotal)}</strong></span></button></div></div><nav class="navigation" aria-label="Navegación principal"><div class="nav-inner"><div class="nav-links">${[['/','Inicio'],['/tienda','Catálogo'],['/como-comprar','Cómo comprar'],['/nosotros','Sobre nosotros'],['/contacto','Sucursales']].map(([p,t])=>`<a href="#${p}" class="${path===p?'active':''}">${t}</a>`).join('')}</div><button class="wholesale-link link-button" data-action="whatsapp-contact">${icon('phone')}Consultar por WhatsApp</button></div></nav></div></header>`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-grid"><div>${brand()}<p>Productos envasados para abastecer heladerías. Venta por caja o bulto.</p><div class="footer-note">${icon('box')}${isWholesale()?'Precios mayoristas en tu cuenta':'Comprá sin registrarte'}</div></div><div><h4>Tu próximo pedido</h4><div class="footer-links"><a href="#/tienda">Catálogo</a><a href="#/como-comprar">Cómo comprar</a><a href="#/carrito">Consultar mi pedido</a><a href="#/cuenta?tab=pedidos">Mis consultas</a></div></div><div><h4>Información</h4><div class="footer-links"><a href="#/contacto">Contacto</a><a href="#/ayuda">Preguntas frecuentes</a><a href="#/legal">Condiciones y privacidad</a></div></div><div><h4>Atención comercial</h4><div class="footer-links"><span>Stock y medios de pago por WhatsApp.</span><span>Retiro en la sucursal elegida.</span>${isAdmin()?'<a href="#/admin">Administración</a>':''}</div></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} La Montevideana</span><span>Venta minorista y mayorista · Productos por caja o bulto</span></div></div></footer>`}
function mobileNav(){const{path}=route();return `<nav class="mobile-nav" aria-label="Accesos móviles"><a href="#/" class="${path==='/'?'active':''}">${icon('home')}Inicio</a><a href="#/tienda" class="${path==='/tienda'?'active':''}">${icon('box')}Catálogo</a><a href="#/como-comprar" class="${path==='/como-comprar'?'active':''}">${icon('info')}Cómo pedir</a><button data-action="cart">${icon('bag')}Pedido (${calc().count})</button><a href="#/cuenta" class="${path==='/cuenta'?'active':''}">${icon('user')}Mi cuenta</a></nav>`}
function crumb(label){return `<div class="breadcrumb"><a href="#/">Inicio</a>${icon('chevron')}<span>${esc(label)}</span></div>`}
function pageHead(title,desc=''){return `<div class="page-title"><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>`}
