function sectionTitle(kicker,title,desc,link,label){return `<div class="section-head"><div>${kicker?`<div class="section-kicker">${kicker}</div>`:''}<h2>${title}</h2>${desc?`<p>${desc}</p>`:''}</div>${link?`<a class="text-link" href="#${link}">${label||'Ver catálogo'}</a>`:''}</div>`}
function productCard(p){return `<article class="product"><button class="fav ${state.favorites.includes(p.id)?'selected':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'Quitar de':'Agregar a'} favoritos: ${esc(p.name)}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button><a class="product-image" href="#/producto/${p.id}"><span class="presentation-label">Por ${saleLabel(p)}</span><img src="${esc(p.image)}" alt="${p.provisional?'Imagen pendiente: ':''}${esc(p.name)}" loading="lazy" width="600" height="480"></a><div class="product-body"><div class="product-brand">${esc(p.family||'VENTA POR '+p.saleUnit.toUpperCase())}</div><h3><a href="#/producto/${p.id}">${esc(p.name)}</a></h3><div class="product-size">${esc(p.size)}</div><div class="product-bottom"><div class="price"><strong>${money(p.price)}</strong><small>${p.price===0?'Precio pendiente de carga':priceLabel()+' por '+saleLabel(p)}</small></div><button class="add" data-action="add" data-id="${p.id}"  aria-label="Agregar ${esc(p.name)} al pedido">${icon('plus')}Agregar</button></div><button class="stock-link" data-action="stock-inquiry" data-id="${p.id}">${icon('phone')}Consultar stock</button></div></article>`}
